import{z as A,x as i,o as l,c as p,q as n,j as s,D as E,d as t,s as B,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"KM 与最大权匹配","description":"","frontmatter":{"title":"KM 与最大权匹配","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hungarian-km.md","filePath":"cs/hungarian-km.md","lastUpdated":1791413859000}'),d={name:"cs/hungarian-km.md"};function m(D,a,h,u,C,c){const r=i("Mermaid");return l(),p("div",null,[a[2]||(a[2]=n('<h1 id="km-与最大权匹配" tabindex="-1">KM 与最大权匹配 <a class="header-anchor" href="#km-与最大权匹配" aria-label="Permalink to &quot;KM 与最大权匹配&quot;">​</a></h1><div class="epigraph"><p>顶标可行时相等子图的完备匹配就是最大权匹配；否则沿交错树改顶标，直到相等子图可完备。</p><footer>—— 据 Kuhn, The Hungarian Method for the Assignment Problem, 1955；Munkres, Algorithms for the Assignment Problem, 1957；Kuhn–Munkres / KM 整理</footer></div><p>上一课<a href="/cs/hopcroft-karp">Hopcroft–Karp</a>给了二分图最大基数。本课加<strong>边权</strong>，求权和最大的匹配（通常 \\(|L|=|R|\\) 的指派）。费用流已能做同一件事；本课给组合的顶标算法。不重写 \\(O(E\\sqrt V)\\) 的无权重。后课一般图带花。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指派：完全二分图，边权 \\(w(x,y)\\)。顶标 \\(lx[x]+ly[y]\\ge w(x,y)\\) 可行。相等子图：取等号的边。若相等子图有完备匹配，则该匹配权 \\(\\sum w=\\sum lx+\\sum ly\\)，而对任何匹配 \\(\\sum w\\le\\sum lx+\\sum ly\\)，故最优。</p><p><span class="marginnote">顶标可以翻译成「给每个点发一张保底价签」：任何一条边两端的价签之和都不低于这条边的权。算法全程只做一件事——不断调整价签，直到「价签之和恰好等于边权」的边（相等子图）里凑得出一条完备匹配；那一刻价签总和就等于最优匹配权。</span></p><p>若无完备：在相等子图里做匈牙利，得交错树。令 \\(\\Delta\\) 为树外松弛量的最小正缺口，树内 \\(L\\) 减 \\(\\Delta\\)、\\(R\\) 加 \\(\\Delta\\)，可行性保持，相等边集合变大。直到完备。</p><p>缺口是顶标，不是再建费用网络。</p><h3 id="km-不是「每次贪心最大边」" tabindex="-1">KM 不是「每次贪心最大边」 <a class="header-anchor" href="#km-不是「每次贪心最大边」" aria-label="Permalink to &quot;KM 不是「每次贪心最大边」&quot;">​</a></h3><p>贪心按权排序加边没有最优保证。顶标是对偶变量，与 LP 对偶同一精神，后课单纯形单元会命名；本课组合叙述。</p><p><span class="marginnote">Kuhn 1955 匈牙利法；Munkres 1957 矩阵形式。KM 常指顶标实现。O(n^3) 是完全图上的常用界。后课 Edmonds 带花处理非二分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化 \\(lx[x]=\\max_y w(x,y)\\)，\\(ly=0\\)。循环：相等子图求最大匹配；失败则改顶标。匹配用上一课的增广（实现上常 \\(O(n)\\) 次 DFS 达到 \\(O(n^3)\\)）。</p><p><span class="marginnote">代入一个 \\(2\\times 2\\) 的小例子：\\(w=[[5,1],[5,1]]\\)。初始 \\(lx=[5,5]\\)、\\(ly=[0,0]\\)，相等子图里两条边都连向 \\(y_1\\)，最大匹配只有 1 条，不完备。树外最小缺口 \\(\\Delta=4\\)：左点顶标降到 1、\\(y_1\\) 升到 4 之后四条边全部进入相等子图，权 6 的完备匹配立刻出现。</span></p>',14)),(l(),s(o,null,{default:E(()=>[B(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAB%5B%22%E5%8F%AF%E8%A1%8C%E9%A1%B6%E6%A0%87%22%5D%20--%3E%20EQ%5B%22%E7%9B%B8%E7%AD%89%E5%AD%90%E5%9B%BE%22%5D%0A%20%20EQ%20--%3E%20PM%5B%22%E5%AE%8C%E5%A4%87%E5%8C%B9%E9%85%8D%EF%BC%9F%22%5D%0A%20%20PM%20--%3E%7C%22%E6%98%AF%22%7C%20OPT%5B%22%E6%9C%80%E5%A4%A7%E6%9D%83%E5%8C%B9%E9%85%8D%22%5D%0A%20%20PM%20--%3E%7C%22%E5%90%A6%22%7C%20DEL%5B%22%E6%94%B9%20%CE%94%20%E6%89%A9%E7%9B%B8%E7%AD%89%E8%BE%B9%22%5D%0A%20%20DEL%20--%3E%20EQ%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"不完全二分：补零边。最大权不必基数最大时，用 0 权或费用流更干净。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"对偶可行保证上界；相等子图完备则原对偶间隙为零。改 \\(\\Delta\\) 使至少一条新边进入相等子图，故有限终止。与最小费用流：源汇与费用 \\(-w\\) 的最大流给出同一指派；KM 是组合对偶。",-1)),(l(),s(o,null,{default:E(()=>[B(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BA%A4%E9%94%99%E6%A0%91%E7%A1%AE%E5%AE%9A%20S%20%E4%B8%8E%20T%22%5D%20--%3E%20IN%5B%22%E6%A0%91%E5%86%85%20L%20%E9%A1%B6%E6%A0%87%E5%87%8F%20%CE%94%22%5D%0A%20%20T%20--%3E%20OUT%5B%22%E6%A0%91%E5%86%85%20R%20%E9%A1%B6%E6%A0%87%E5%8A%A0%20%CE%94%22%5D%0A%20%20IN%20--%3E%20CHK%5B%22%E6%A3%80%E6%9F%A5%20lx%20%2B%20ly%20%E4%B8%8E%20w%20%E7%9A%84%E5%85%B3%E7%B3%BB%22%5D%0A%20%20OUT%20--%3E%20CHK%0A%20%20CHK%20--%3E%7C%22%E6%A0%91%E5%86%85%E8%BE%B9%EF%BC%9A%E5%92%8C%E4%B8%8D%E5%8F%98%22%7C%20KEEP%5B%22%E5%B7%B2%E5%8C%B9%E9%85%8D%E8%BE%B9%E4%BB%8D%E6%98%AF%E7%9B%B8%E7%AD%89%E8%BE%B9%22%5D%0A%20%20CHK%20--%3E%7C%22%E6%A0%91%E5%A4%96%E8%BE%B9%EF%BC%9A%E6%9C%80%E5%B0%8F%E7%BC%BA%E5%8F%A3%E8%A2%AB%E5%8E%8B%E5%88%B0%E9%9B%B6%22%7C%20NEW%5B%22%E6%96%B0%E8%BE%B9%E8%BF%9B%E5%85%A5%E7%9B%B8%E7%AD%89%E5%AD%90%E5%9B%BE%22%5D%0A%20%20NEW%20--%3E%20LOOP%5B%22%E5%9B%9E%E5%88%B0%E5%8C%B9%E9%85%8D%E6%AD%A5%E9%AA%A4%EF%BC%8C%E7%9B%B8%E7%AD%89%E5%AD%90%E5%9B%BE%E5%8F%98%E5%A4%A7%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：以为 \\(\\Delta\\) 应该加在「最好的那条边」上。实际上树内 L 减 \\(\\Delta\\)、树内 R 加 \\(\\Delta\\)，两个方向正好相抵，所以树内已有边的 \\(lx+ly\\) 不变、不会破坏可行性；被压缩的只有从树内左点指向树外右点的边的缺口——这正是「可行性保持、相等边只增不减」的原因。</span></p><p>不要把顶标改成随意加减破坏 \\(lx+ly\\ge w\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写一般图最大权（Edmonds 带权更重）。不写拍卖算法。后课默认：二分最大权指派 = KM 或费用流。下一课非二分最大基数：花。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可行顶标给出权的上界；相等子图完备即最优。</li><li>无完备则改 \\(\\Delta\\) 扩相等边。</li><li>与费用流等价，本课要组合顶标。</li><li>出处：Kuhn, 1955；Munkres, 1957。</li></ul>',6))])}const _=A(d,[["render",m]]);export{x as __pageData,_ as default};
